
create table if not exists public.bil_official_food_catalog (
  id uuid primary key default gen_random_uuid(),
  source_id text not null unique,
  source_name text not null,
  source_url text not null,
  canonical_name text not null check (length(canonical_name) between 2 and 180),
  localized_names jsonb not null default '{}'::jsonb,
  aliases jsonb not null default '[]'::jsonb,
  country_code text not null check (length(country_code) = 2),
  serving_amount numeric not null check (serving_amount > 0),
  serving_unit text not null,
  calories_kcal numeric not null check (calories_kcal >= 0),
  protein_g numeric not null check (protein_g >= 0),
  carbohydrate_g numeric not null check (carbohydrate_g >= 0),
  fat_g numeric not null check (fat_g >= 0),
  fiber_g numeric check (fiber_g >= 0),
  sugar_g numeric check (sugar_g >= 0),
  sodium_mg numeric check (sodium_mg >= 0),
  potassium_mg numeric check (potassium_mg >= 0),
  calcium_mg numeric check (calcium_mg >= 0),
  magnesium_mg numeric check (magnesium_mg >= 0),
  phosphorus_mg numeric check (phosphorus_mg >= 0),
  iron_mg numeric check (iron_mg >= 0),
  vitamin_c_mg numeric check (vitamin_c_mg >= 0),
  nutrient_evidence_mask integer not null check (
    nutrient_evidence_mask between 0 and 2147483647
  ),
  published_at date not null,
  updated_at timestamptz not null default now()
);

alter table public.bil_official_food_catalog enable row level security;
revoke all on public.bil_official_food_catalog from public, anon, authenticated;
grant select on public.bil_official_food_catalog to service_role;

create index if not exists bil_official_food_catalog_search_trgm_idx
  on public.bil_official_food_catalog using gin (
    lower(canonical_name || ' ' || localized_names::text || ' ' || aliases::text)
    extensions.gin_trgm_ops
  );

with source_rows as (
  select *
  from jsonb_to_recordset($catalog$
