insert into public.bil_official_food_catalog (
  source_id, source_name, source_url, canonical_name, localized_names, aliases,
  country_code, serving_amount, serving_unit, calories_kcal, protein_g,
  carbohydrate_g, fat_g, fiber_g, sugar_g, sodium_mg, potassium_mg,
  calcium_mg, magnesium_mg, phosphorus_mg, iron_mg, vitamin_c_mg,
  nutrient_evidence_mask, published_at, updated_at
)
select
  source_id,
  'Saudi Food and Drug Authority - Saudi Food Composition Tables',
  evidence_url,
  canonical_name,
  localized_names,
  aliases,
  country_code,
  serving_amount,
  serving_unit,
  calories_kcal,
  protein_g,
  carbohydrate_g,
  fat_g,
  fiber_g,
  sugar_g,
  sodium_mg,
  potassium_mg,
  calcium_mg,
  magnesium_mg,
  phosphorus_mg,
  iron_mg,
  vitamin_c_mg,
  nutrient_evidence_mask,
  date '2026-06-25',
  now()
from source_rows
on conflict (source_id) do update set
  source_name = excluded.source_name,
  source_url = excluded.source_url,
  canonical_name = excluded.canonical_name,
  localized_names = excluded.localized_names,
  aliases = excluded.aliases,
  country_code = excluded.country_code,
  serving_amount = excluded.serving_amount,
  serving_unit = excluded.serving_unit,
  calories_kcal = excluded.calories_kcal,
  protein_g = excluded.protein_g,
  carbohydrate_g = excluded.carbohydrate_g,
  fat_g = excluded.fat_g,
  fiber_g = excluded.fiber_g,
  sugar_g = excluded.sugar_g,
  sodium_mg = excluded.sodium_mg,
  potassium_mg = excluded.potassium_mg,
  calcium_mg = excluded.calcium_mg,
  magnesium_mg = excluded.magnesium_mg,
  phosphorus_mg = excluded.phosphorus_mg,
  iron_mg = excluded.iron_mg,
  vitamin_c_mg = excluded.vitamin_c_mg,
  nutrient_evidence_mask = excluded.nutrient_evidence_mask,
  published_at = excluded.published_at,
  updated_at = now();

create or replace function public.bil_search_community_foods(
  p_query text,
  p_limit integer default 10
)
returns table (
  id uuid,
  canonical_name text,
  localized_names jsonb,
  aliases jsonb,
  barcode text,
  serving_amount numeric,
  serving_unit text,
  calories_kcal numeric,
  protein_g numeric,
  carbohydrate_g numeric,
  fat_g numeric,
  fiber_g numeric,
  sugar_g numeric,
  sodium_mg numeric,
  potassium_mg numeric,
  calcium_mg numeric,
  magnesium_mg numeric,
  phosphorus_mg numeric,
  iron_mg numeric,
  vitamin_c_mg numeric,
  nutrient_evidence_mask integer,
  status text,
  verified boolean,
  updated_at timestamptz
)
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_query text := lower(trim(coalesce(p_query, '')));
  v_limit integer := least(greatest(coalesce(p_limit, 10), 1), 20);
begin
  if auth.uid() is null then
    raise exception 'authentication_required';
  end if;
  if char_length(v_query) < 2 then
    return;
  end if;

  return query
  with candidates as (
    select
      s.id,
      s.canonical_name,
      s.localized_names,
      s.aliases,
      s.barcode,
      coalesce(s.serving_amount, s.serving_grams, 100) as serving_amount,
      coalesce(s.serving_unit, 'g') as serving_unit,
      s.calories_kcal,
      s.protein_g,
      s.carbohydrate_g,
      s.fat_g,
      s.fiber_g,
      s.sugar_g,
      s.sodium_mg,
      s.potassium_mg,
      s.calcium_mg,
      s.magnesium_mg,
      s.phosphorus_mg,
      s.iron_mg,
      s.vitamin_c_mg,
      s.nutrient_evidence_mask,
      s.status,
      (s.status = 'approved') as verified,
      s.updated_at,
      lower(s.canonical_name || ' ' || coalesce(s.brand, '') || ' ' ||
        s.localized_names::text || ' ' || s.aliases::text) as search_text
    from public.bil_community_food_submissions s
    where s.withdrawn_at is null
      and s.status in ('pending', 'approved')
      and s.product_kind in ('food', 'beverage', 'alcohol')
      and s.serving_amount is not null

    union all

    select
      f.id,
      f.canonical_name,
      f.localized_names,
      f.aliases,
      null::text as barcode,
      f.serving_amount,
      f.serving_unit,
      f.calories_kcal,
      f.protein_g,
      f.carbohydrate_g,
      f.fat_g,
      f.fiber_g,
      f.sugar_g,
      f.sodium_mg,
      f.potassium_mg,
      f.calcium_mg,
      f.magnesium_mg,
      f.phosphorus_mg,
      f.iron_mg,
      f.vitamin_c_mg,
      f.nutrient_evidence_mask,
      'approved'::text as status,
      true as verified,
      f.updated_at,
      lower(f.canonical_name || ' ' || f.localized_names::text || ' ' ||
        f.aliases::text) as search_text
    from public.bil_official_food_catalog f
  )
  select
    c.id, c.canonical_name, c.localized_names, c.aliases, c.barcode,
    c.serving_amount, c.serving_unit, c.calories_kcal, c.protein_g,
    c.carbohydrate_g, c.fat_g, c.fiber_g, c.sugar_g, c.sodium_mg,
    c.potassium_mg, c.calcium_mg, c.magnesium_mg, c.phosphorus_mg,
    c.iron_mg, c.vitamin_c_mg, c.nutrient_evidence_mask, c.status,
    c.verified, c.updated_at
  from candidates c
  where c.search_text like '%' || v_query || '%'
     or similarity(c.search_text, v_query) >= 0.30
  order by
    c.verified desc,
    exists (
      select 1 from jsonb_each_text(c.localized_names) localized
      where lower(localized.value) = v_query
    ) desc,
    exists (
      select 1 from jsonb_array_elements_text(c.aliases) alias
      where lower(alias) = v_query
    ) desc,
    (lower(c.canonical_name) = v_query) desc,
    (c.search_text like v_query || '%') desc,
    similarity(c.search_text, v_query) desc,
    c.updated_at desc
  limit v_limit;
end;
$$;

revoke all on function public.bil_search_community_foods(text, integer)
  from public, anon;
grant execute on function public.bil_search_community_foods(text, integer)
  to authenticated;

